from pathlib import Path
import json,html,argparse
from PIL import Image
p=argparse.ArgumentParser();p.add_argument('run');p.add_argument('--suite',default='All');args=p.parse_args()
base=Path(__file__).resolve().parent.parent;journey=base/'QA'/args.run/args.suite/'Journey';out=base/'Captures';out.mkdir(exist_ok=True)
labels={'Gems': ['Gems · contact flash and fractured jewel', 'SpectacleR15'], 'Row': ['Horizontal energy sweep', 'SpectacleR15'], 'Column': ['Vertical energy sweep', 'SpectacleR15'], 'Burst': ['Bomb · explosive release', 'SpectacleR15'], 'BogatyrMace': ['Mace · heavy strike', 'SpectacleR15'], 'Firebird': ['Firebird · radiant wing flare', 'SpectacleR15'], 'LivingLight': ['Living Light · sapphire release', 'SpectacleR15'], 'SeaPearl': ['Sea Pearl · upward energy spiral', 'SpectacleR15'], 'Creation': ['Special creation · converging charge', 'CausalR13'], 'Chain': ['Line → bomb chain reaction', 'CausalR13'], 'Conversion': ['Rainbow · branching conversion arcs', 'CausalR13'], 'PayloadRow': ['Firebird flight · row payload', 'CausalR13'], 'PayloadColumn': ['Firebird flight · column payload', 'CausalR13'], 'PayloadBurst': ['Firebird flight · bomb payload', 'CausalR13'], 'Crate_First': ['Wood · damage', 'MaterialR14'], 'Crate_Final': ['Wood · final break', 'MaterialR14'], 'Ice_First': ['Ice · damage', 'MaterialR14'], 'Ice_Final': ['Ice · final break', 'MaterialR14'], 'Chain_First': ['Chain links · damage', 'MaterialR14'], 'Chain_Final': ['Chain links · final break', 'MaterialR14'], 'RunicSeal_First': ['Runic seal · damage', 'MaterialR14'], 'RunicSeal_Final': ['Runic seal · final break', 'MaterialR14']}
items=[]
for key,(label,prefix) in labels.items():
    samples=[(int(line.split('\t')[0]),float(line.split('\t')[1])) for line in (journey/(key+'_Frames.tsv')).read_text().splitlines()]
    before=journey/('Mechanics_'+prefix+'_'+key+'_Before.png');after=journey/('Mechanics_'+prefix+'_'+key+'_After.png')
    paths=[before]+[journey/('Mechanics_'+prefix+'_'+key+'_'+str(i).zfill(2)+'.png') for i,t in samples]+[after]
    images=[Image.open(path).convert('RGB') for path in paths]
    times=[400]+[max(1,round((samples[i+1][1]-t)*1000)) if i+1<len(samples) else 160 for i,(index,t) in enumerate(samples)]+[900]
    dest=out/(key+'.webp');images[0].save(dest,save_all=True,append_images=images[1:],duration=times,loop=0,lossless=True,method=4)
    for image in images:image.close()
    frames=[str(path.relative_to(base)) for path in paths]
    items.append({'key':key,'label':label,'animation':str(dest.relative_to(base)),'frames':frames,'samples':len(samples),'baseline':('../R15/Captures/'+key+'.webp') if prefix=='SpectacleR15' else None,'timestampFile':str((journey/(key+'_Frames.tsv')).relative_to(base))})
(base/'QA/ReviewCaptures.json').write_text(json.dumps(items,indent=2))
options=''.join('<option value="'+str(i)+'">'+html.escape(item['label'])+'</option>' for i,item in enumerate(items))
(base/'Gameplay_Mechanics_R16_Review.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gameplay R16 — Energy and Impact Redesign</title><style>
*{box-sizing:border-box}body{background:#0c1420;color:#efdebb;margin:0;font:17px/1.5 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px}h1,h2{color:#e8be66;line-height:1.2}a{color:#afd7ff}.layout{display:grid;grid-template-columns:minmax(260px,390px) 1fr;gap:24px;align-items:start}section{padding:18px;border:1px solid #655536;border-radius:12px;margin:20px 0;background:#121f2b}img{display:block;width:100%;height:auto}select,button{font:inherit;color:#f0debb;background:#20394a;border:1px solid #91764b;padding:10px;margin:5px 0;max-width:100%;border-radius:5px}select{width:100%}button{cursor:pointer}input{width:100%}label{display:block}small{display:block;color:#bfc7ce}.status{min-height:3em} @media(max-width:700px){main{padding:14px}.layout{grid-template-columns:1fr}.portrait{max-width:390px;margin:auto}}
</style><main><p>Gameplay Mechanics · R16</p><h1>A complete energy and impact pass</h1><p>The R4 effects now use a dedicated additive light pass, stronger silhouettes and a staged impact response. Approved gems, item and booster artwork remain in place.</p><div class="layout"><section class="portrait"><label for="sequence">Actual Unity sequence</label><select id="sequence">'''+options+'''</select><button id="play">Play sequence</button> <button id="stop">Inspect frame</button> <button id="baseline">Compare R15 playback</button><label for="frame">Frame</label><input id="frame" type="range" min="0" value="0"><p id="status" class="status"></p><a id="full" target="_blank" rel="noopener">Open full-size capture</a><img id="screen" alt="Actual Unity sandbox animation capture"><small>576 × 1280 Unity test captures. Sampled opening sequence followed by the final settled state. Sample intervals are preserved, with review holds before/after; no interpolated or generated frames. Silent preview, not a frame-rate benchmark.</small></section><div><section><h2>Implemented</h2><ul><li>Gems squash at contact and release larger spinning facets, luminous cores and sparkling wakes.</li><li>Directional items discharge bright travelling heads, broad trails and curling energy strands.</li><li>Bombs and booster strikes have a sustained hot core, expanding shock front and radial flares.</li><li>Creation draws sparks inward; rainbow links branch as bright jagged arcs.</li><li>Firebirds fly with continuous energy ribbons and visible carried items.</li><li>All four boosters have stronger poses and distinct light patterns. Obstacles throw larger material fragments with a separate impact flash.</li></ul><p>The new sequence applies to PrototypeR4 in the development sandbox. Production Legacy rules and the five round move budgets are unchanged.</p></section><section><h2>Verification</h2><p id="tests"></p><p>Input release, final plan hashes, all 15 special pairs, five rounds, recording, recovery, and prior effects/audio are checked. See the evidence for exact scope.</p><p><a href="ImplementationReport.md">Implementation report</a> · <a href="QA/Verification.json">Test results</a> · <a href="QA/Scope.json">Changed files</a></p></section><section><h2>Review in Unity</h2><p>Home → Development → Gameplay Mechanics Sandbox. Use R4 rounds and Fixtures to compare gem clears, directional items, bombs and the four inventory boosters.</p><p>These are controlled commands using the existing artwork. The first and final obstacle hits use separate two-layer and one-layer setups. The R15 comparison button switches this same portrait to the previous version; these are separate automated recordings, not synchronized footage. Physical-phone performance and player acceptance remain outstanding.</p></section></div></div></main><script>
const items='''+json.dumps(items)+''';const sequence=document.querySelector('#sequence'),frame=document.querySelector('#frame'),picture=document.querySelector('#screen'),status=document.querySelector('#status');
function still(){const item=items[+sequence.value];picture.src=item.frames[+frame.value];document.querySelector('#full').href=picture.src;status.textContent=item.label+' · frame '+(+frame.value+1)+' / '+item.frames.length;picture.alt='Actual Unity capture: '+status.textContent;}
function select(){document.querySelector('#baseline').disabled=!items[+sequence.value].baseline;frame.max=items[+sequence.value].frames.length-1;frame.value=0;still();}
document.querySelector('#baseline').onclick=()=>{const item=items[+sequence.value];if(item.baseline){picture.src=item.baseline;document.querySelector('#full').href=picture.src;status.textContent=item.label+' · previous R15 playback';}};sequence.onchange=select;frame.oninput=still;document.querySelector('#stop').onclick=still;document.querySelector('#play').onclick=()=>{const item=items[+sequence.value];picture.src=item.animation;document.querySelector('#full').href=picture.src;status.textContent=item.label+' · sampled Unity playback';};select();
</script></html>''')
review=base/'Gameplay_Mechanics_R16_Review.html'
verification=json.loads((base/'QA/Verification.json').read_text())
review.write_text(review.read_text().replace('<p id="tests"></p>','<p id="tests">'+str(verification['playModePassed'])+' PlayMode checks passed; no failures or skips in the final runs.</p>'))
